#!/usr/bin/env python3
import json, subprocess, sys
REPO = "abhilashenair/uppercrest"
BRANCH = "Main"
TOKEN = sys.argv[1] if len(sys.argv) > 1 else open("/home/admin/.ghtoken").read().strip()

files = {
    "index.html": "",
    "about.html": "",
    "gallery.html": "",
    "facilities.html": "",
    "location.html": "",
    "faq.html": "",
    "css/style.css": "",
    "js/components.js": "",
    "js/main.js": "",
}

for filepath, content in files.items():
    print(f"Pushing {filepath}...", end=" ", flush=True)
    r = subprocess.run(["curl","-s","-H",f"Authorization: token {TOKEN}",
        f"https://api.github.com/repos/{REPO}/contents/{filepath}?ref={BRANCH}"],
        capture_output=True, text=True)
    try:
        d = json.loads(r.stdout)
        sha = d.get("sha","")
    except:
        sha = ""
    payload = {"message": f"Deploy {filepath}", "content": content, "branch": BRANCH}
    if sha:
        payload["sha"] = sha
    import tempfile, os
    tmpf = tempfile.mktemp(suffix=".json")
    with open(tmpf, "w") as f:
        json.dump(payload, f)
    r2 = subprocess.run(["curl","-s","-X","PUT",
        "-H",f"Authorization: token {TOKEN}",
        "-H","Content-Type: application/json",
        "--data-binary", f"@{tmpf}",
        f"https://api.github.com/repos/{REPO}/contents/{filepath}"],
        capture_output=True, text=True)
    os.unlink(tmpf)
    try:
        d2 = json.loads(r2.stdout)
        c = d2.get("content")
        if c:
            print(f"OK ({c['sha'][:8]})")
        else:
            print(f"ERR: {str(d2)[:80]}")
    except Exception as ex:
        print(f"ERR: {ex}")

print("\nAll done! Now run: sudo bash /home/admin/deploy.sh")
